import{actions,qualities,bodyParts,goalkeeperBodyParts,areas,goalAreas,shotOriginAreas,goalkeeperOutcomes,freshState,createMatchBackup,matchBackupFilename,createStructuredMatchExportV16,structuredExportFilename,createAiHandoffReportV16,handoffReportFilename,formatMatchClock,liveSeconds,toggleRunningClock,mergeDictationText,upsertFullTimeEvent,upsertTerminatedEvent,makeEvent,makeQuickNoteEvent,makeSpecialEvent,makeSubstitutionEvent,scoreFromEvents,parseLineupBlock,lineupWarnings,generateObservationSentence}from'./model.js';
const KEY='scoutline-sprint1',CLOCK_HOLD_MS=1200;let state=load();let view=state.match?(['fulltime','terminated'].includes(state.clock?.period)?'summary':'live'):'home';let selected=null;let timer;let pendingImport=null;let pendingRestore=null;let pendingExport=null;let draftObservation=null;let endingMode=null;let clockHoldTimer=null;let savingObservation=false;let savedNoticeTimer=null;let savedNotice='';let activeDictation=null;
const TEAM_COLOURS=[['#ef4444','Red'],['#2563eb','Blue'],['#facc15','Yellow'],['#ffffff','White'],['#111827','Black'],['#16a34a','Green'],['#f97316','Orange'],['#7c3aed','Purple'],['#ec4899','Pink'],['#6b7280','Grey']];
function load(){try{const stored={...freshState(),...JSON.parse(localStorage.getItem(KEY)||'{}')};stored.lineups=stored.lineups||{home:null,away:null};stored.clock={...freshState().clock,...stored.clock};if(stored.clock.period==='pre'&&(stored.clock.running||stored.clock.seconds>0||stored.events.length))stored.clock.period='first';return stored}catch{return freshState()}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
const esc=value=>String(value??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function icon(name){return `<span class="icon" aria-hidden="true">${{pitch:'⌗',clock:'◷',plus:'＋',note:'✎',mic:'●',back:'‹',play:'▶',pause:'Ⅱ',import:'⇩'}[name]||name}</span>`}
function shell(content){return `<main class="shell">${content}</main>`}
function clockText(){return formatMatchClock(liveSeconds(state.clock),state.clock.endedPeriod||state.clock.period)}
function render(){clearInterval(timer);document.querySelector('#app').innerHTML=view==='home'?home():view==='summary'?matchSummary():live();if(view==='home')document.querySelector('#app').insertAdjacentHTML('beforeend','<div class="restore-launch"><button id="choose-backup">↥ Restore match backup</button><input id="backup-file" type="file" accept="application/json,.json" hidden></div>');else document.querySelector('#app').insertAdjacentHTML('beforeend','<div class="report-launch"><button id="report-notes">✎ Report notes & assessments</button></div>');bind();if(view==='live'){timer=setInterval(()=>{const e=document.querySelector('#clock');if(e)e.textContent=clockText()},500)}}
function home(){const unfinished=state.match?.reportStatus==='unfinished';return shell(`<header class="brand"><div class="mark">S</div><div><small>FOOTBALL INTELLIGENCE</small><h1>Scoutline</h1></div></header><section class="hero"><p class="eyebrow">MATCHDAY WORKSPACE</p><h2>See the game.<br><em>Capture the detail.</em></h2><p class="lead">Fast, private, offline-first observations built for the touchline.</p><button class="primary" id="new-match">${icon('plus')} Start live match</button></section><section><div class="section-title"><h3>Recent matches</h3><span>Stored on this device</span></div>${state.match?`<button class="match-card ${unfinished?'unfinished':''}" id="resume"><div class="date">${new Date(state.match.createdAt).toLocaleDateString('en-GB',{day:'2-digit',month:'short'}).toUpperCase()}</div><div><b>${esc(state.match.home)} <i>vs</i> ${esc(state.match.away)}</b><span>${state.events.length} events · ${state.players.length} players${unfinished?' · Finish report':['fulltime','terminated'].includes(state.clock.period)?` · ${state.clock.period==='fulltime'?'Full-time':'Ended early'}`:''}</span></div><strong>›</strong></button>`:`<div class="empty"><span>${icon('pitch')}</span><b>No matches yet</b><p>Your live sessions will appear here.</p></div>`}</section><footer>PRIVATE BY DEFAULT <span>•</span> OFFLINE READY</footer>`)}
function matchSetup(){const today=new Date().toISOString().slice(0,10);return `<div class="modal-wrap"><form class="modal" id="match-form"><button type="button" class="close">×</button><p class="eyebrow">NEW SESSION</p><h2>Match details</h2><label>Home team<input name="home" required placeholder="Home team"></label><label>Away team<input name="away" required placeholder="Away team"></label><label>Competition<input name="competition" required placeholder="League or competition"></label><label>Venue<input name="venue" required placeholder="Ground or venue"></label><div class="row"><label>Match date<input name="matchDate" type="date" value="${today}" required></label><label>Kick-off<input name="kickOff" type="time"></label></div><button class="primary">Create match</button></form></div>`}
function missingMetadata(){return['matchDate','venue','competition'].filter(field=>!String(state.match?.[field]||'').trim())}
function metadataCompletionForm(){const m=state.match||{},today=new Date(m.createdAt||Date.now()).toISOString().slice(0,10);return `<div class="modal-wrap"><form class="modal" id="metadata-form"><button type="button" class="close">×</button><p class="eyebrow">EXPORT CHECK</p><h2>Complete match details</h2><p class="helper">The reporting workspace needs these details. They will be saved to this match before the export is created.</p><label>Competition<input name="competition" required value="${esc(m.competition||'')}" placeholder="League or competition"></label><label>Venue<input name="venue" required value="${esc(m.venue||'')}" placeholder="Ground or venue"></label><div class="row"><label>Match date<input name="matchDate" type="date" required value="${esc(m.matchDate||today)}"></label><label>Kick-off<input name="kickOff" type="time" value="${esc(m.kickOff||'')}"></label></div><button class="primary">Save details and continue export</button></form></div>`}
function lineupStatus(){const count=['home','away'].filter(side=>state.lineups[side]).length;return `<section class="setup-card ${count===2?'ready':''}"><div><small>${state.match.placementConfirmed?'POSITIONS CONFIRMED':count===2?'LINE-UPS READY':'PRE-MATCH SETUP'}</small><b>${state.match.placementConfirmed?'Ready to start the match':count===2?'Arrange players on the pitch':count===1?'One of two teams imported':'Import confirmed line-ups'}</b></div><button id="import-lineup">${icon('import')} Import</button>${count?`<div class="lineup-sources">${['home','away'].map(side=>state.lineups[side]?`<span><i>✓</i> ${esc(state.lineups[side].team)}${state.lineups[side].sourceUrl?` <a href="${esc(state.lineups[side].sourceUrl)}" target="_blank" rel="noopener">source ↗</a>`:''}</span>`:'').join('')}</div>`:''}</section>`}
function periodLabel(){return{pre:'PRE-MATCH',first:'FIRST HALF',halftime:'HALF-TIME',second:'SECOND HALF',fulltime:'FULL-TIME',terminated:'SCOUTING ENDED'}[state.clock.period]||'LIVE'}
function matchControls(begun){if(!begun)return'';if(state.clock.period==='first')return`<button id="half-time" class="match-state-btn">Half-time</button>`;if(state.clock.period==='halftime')return`<div class="interval-actions"><button id="edit-half-time">${state.match.halfTimeNote?'Edit':'Add'} half-time notes</button><button id="second-half" class="accent">${icon('play')} Start second half</button></div>`;return''}
function clockControl(begun){const active=begun&&['first','second'].includes(state.clock.period),status=state.clock.period==='halftime'?'HALF-TIME':state.clock.period==='fulltime'?'FULL-TIME':state.clock.period==='terminated'?'ENDED':state.clock.running?'RUNNING':'PAUSED',instruction=active?`Hold to ${state.clock.running?'pause':'resume'}`:'Clock locked';return `<div class="clock-control ${status.toLowerCase().replace(/[^a-z]+/g,'-')}"><button id="clock-toggle" class="clock-btn" ${active?'':'disabled'} aria-label="${status}. ${instruction}" style="--hold-duration:${CLOCK_HOLD_MS}ms">${icon(state.clock.running?'pause':'play')} <b id="clock">${clockText()}</b><span class="hold-progress" aria-hidden="true"></span></button><span class="clock-status">${status}</span><small>${instruction}</small></div>`}
function live(){if(!state.match)return home();const starters=state.players.filter(p=>p.squadRole!=='substitute'),firstSide=state.match.deployment?.firstSide,placingSecond=state.match.deployment?.stage==='team2'&&!state.lineups[firstSide==='home'?'away':'home'],visibleStarters=placingSecond?starters.filter(p=>p.teamSide!==firstSide):starters;const subs=state.players.filter(p=>p.squadRole==='substitute');const begun=state.clock.period!=='pre'||state.clock.running||state.clock.seconds>0||state.events.length>0,score=scoreFromEvents(state.events),ending=endingMode==='options'?endOptions():endingMode==='fulltime'?fullTimeForm():endingMode==='terminate'?terminateForm():'';return shell(`<header class="live-head"><button class="ghost" id="home">${icon('back')}</button><div class="match-heading"><small>${esc(state.match.competition||'MATCH SCOUTING')}</small><h1>${esc(state.match.home)} <i>v</i> ${esc(state.match.away)}</h1></div><div class="running-score" aria-label="Score ${score.home} to ${score.away}"><b>${score.home}</b><i>–</i><b>${score.away}</b></div><span class="live-pill">● ${periodLabel()}</span></header>${lineupStatus()}<section class="scorebar">${clockControl(begun)}<span>${state.events.length} events</span><button id="end-session" class="text-btn">End</button></section><button class="backup-button" id="download-backup">⇩ Download match backup</button>${matchControls(begun)}<section class="pitch-wrap">${placingSecond?`<div class="placement-notice">Team 1 is temporarily hidden while you place Team 2.</div>`:''}<div class="pitch" id="pitch"><div class="half"></div><div class="circle"></div><div class="box top"></div><div class="box bottom"></div>${visibleStarters.map(player=>playerMarker(player)).join('')}</div><div class="pitch-actions"><button id="add-player">${icon('plus')} Add player</button>${begun&&!['fulltime','terminated'].includes(state.clock.period)&&subs.length?`<button id="make-substitution">⇄ Substitution</button>`:''}</div></section>${preMatchAction(begun)}${subs.length?bench(subs):''}<section class="timeline"><div class="section-title"><h3>Timeline</h3><span>Latest first</span></div>${state.events.length?state.events.slice().reverse().map(timelineEvent).join(''):`<div class="empty compact"><b>No events yet</b><p>Tap a player to record an action.</p></div>`}</section>${selected?observationPanel(state.players.find(p=>p.id===selected)):''}${ending}${savedNotice?`<div class="saved-toast" role="status" aria-live="polite">✓ ${esc(savedNotice)}</div>`:''}`)}
function timelineEvent(e){const time=formatMatchClock(e.second,e.period||state.clock.endedPeriod||state.clock.period);if(e.type==='half-time')return`<article class="event system-event"><time>${time}</time><span class="quality"></span><div><b>HALF-TIME</b><blockquote>${esc(e.comment||'First half complete.')}</blockquote></div></article>`;if(e.type==='full-time')return`<article class="event system-event end-event"><time>${time}</time><span class="quality"></span><div><b>FULL-TIME</b><blockquote>${esc(e.comment||'Match completed.')}</blockquote></div></article>`;if(e.type==='terminated')return`<article class="event system-event terminated-event"><time>${time}</time><span class="quality"></span><div><b>SCOUTING ENDED EARLY</b><blockquote>${esc(e.comment)}</blockquote></div></article>`;if(e.type==='substitution')return`<article class="event system-event substitution-event"><time>${time}</time><span class="quality"></span><div><span class="event-team">${esc(e.teamName)}</span><b>⇄ SUBSTITUTION</b><blockquote>${esc(e.comment)}</blockquote></div></article>`;if(e.type==='quick-note')return`<article class="event quick-note-event"><time>${time}</time><span class="quality ${(e.quality||'').toLowerCase()}"></span><div>${e.teamName?`<span class="event-team">${esc(e.teamName)}</span>`:''}<b>✎ ${e.scope==='player'?`#${esc(e.number)} ${esc(e.playerName)}`:e.scope==='team'?'TEAM NOTE':'MATCH NOTE'}</b><blockquote>${esc(e.comment||e.note)}</blockquote></div></article>`;const team=e.teamName?`<span class="event-team">${esc(e.teamName)}</span>`:'';const legacy=!e.comment;return `<article class="event"><time>${time}</time><span class="quality ${(e.quality||'').toLowerCase()}"></span><div>${team}<b>#${esc(e.number)} ${esc(e.playerName)}</b>${legacy?`<p>${esc(e.quality)} · ${esc(e.action)}${e.detail?' · '+esc(e.detail):''}</p>${e.note?`<blockquote>${esc(e.note)}</blockquote>`:''}`:`<blockquote>${esc(e.comment)}</blockquote>`}</div></article>`}
function preMatchAction(begun){if(begun)return'';const count=['home','away'].filter(side=>state.lineups[side]).length,stage=state.match.deployment?.stage;if(count===0)return`<div class="next-step muted"><b>Next: add Team 1</b><span>Import a confirmed line-up, choose its icon colour, then place the players.</span></div>`;if(count===1&&stage!=='team2')return`<div class="next-step"><b>Happy with Team 1 positions?</b><span>Team 1 will remain visible until you continue.</span><button id="add-team-two">Now add Team 2</button></div>`;if(count===1)return`<div class="next-step muted"><b>Now add Team 2</b><span>Team 1 is temporarily hidden to make placement easier.</span></div>`;if(!state.match.placementConfirmed)return`<div class="next-step"><b>Review both teams together</b><span>Adjust any overlapping icons, then confirm the final positions.</span><button id="confirm-placement">Confirm player positions</button></div>`;return`<div class="next-step confirmed"><b>✓ Player positions confirmed</b><span>Everything is ready for kick-off.</span><button id="start-match">${icon('play')} Start match</button></div>`}
