function confirmImport(e){e.preventDefault();const d=new FormData(e.target),side=d.get('side'),lineup={...pendingImport.lineup,team:d.get('team'),source:d.get('source'),sourceUrl:d.get('sourceUrl'),published:d.get('published'),status:d.get('status'),colour:d.get('teamColour')};const readRows=role=>d.getAll(`${role}-index`).map(i=>({number:d.get(`${role}-number-${i}`).trim(),name:d.get(`${role}-name-${i}`).trim(),goalkeeper:d.get(`${role}-goalkeeper-${i}`)==='on',captain:d.get(`${role}-captain-${i}`)==='on'})).filter(p=>p.name);lineup.starters=readRows('starter');lineup.substitutes=readRows('substitute');lineup.importedAt=Date.now();const firstImport=!state.lineups.home&&!state.lineups.away;state.players=state.players.filter(p=>p.teamSide!==side||!p.imported);state.players.push(...createSquad(lineup,side));state.lineups[side]=lineup;state.match.deployment=firstImport?{firstSide:side,stage:'team1'}:{...(state.match.deployment||{firstSide:side==='home'?'away':'home'}),stage:'review'};state.match.placementConfirmed=false;save();pendingImport=null;document.querySelector('.modal-wrap').remove();render()}
