function endFirstHalf(e){e.preventDefault();const seconds=liveSeconds(state.clock);state.clock={...state.clock,seconds,running:false,startedAt:null,period:'halftime',firstHalfEndedAt:seconds};save();document.querySelector('.modal-wrap').remove();render();openHalfTimeNotes()}
function openHalfTimeNotes(){addOverlay(halfTimeNotes());document.querySelector('#half-time-form').addEventListener('submit',saveHalfTimeNotes);document.querySelector('#dictate')?.addEventListener('click',dictate)}
