function startSecondHalf(){state.clock={...state.clock,seconds:2700,running:true,startedAt:Date.now(),period:'second'};save();render()}
function openSubstitution(){selected=null;draftObservation=null;addOverlay(substitutionForm());populateSubstitutionPlayers();document.querySelector('#sub-team').addEventListener('change',populateSubstitutionPlayers);document.querySelector('#substitution-form').addEventListener('submit',saveSubstitution)}
function saveSubstitution(e){e.preventDefault();const d=new FormData(e.target),playerOff=state.players.find(p=>p.id===d.get('playerOff')),playerOn=state.players.find(p=>p.id===d.get('playerOn'));if(!playerOff||!playerOn)return;const oldPosition={x:playerOff.x,y:playerOff.y};playerOff.squadRole='substitute';playerOff.x=50;playerOff.y=50;playerOn.squadRole='starter';playerOn.x=oldPosition.x;playerOn.y=oldPosition.y;state.events.push({...makeSubstitutionEvent({teamName:teamNameFor(playerOff),teamSide:playerOff.teamSide,playerOff,playerOn,second:liveSeconds(state.clock)}),period:state.clock.period});save();document.querySelector('.modal-wrap').remove();render()}
function openEndOptions(){selected=null;draftObservation=null;endingMode='options';render()}
function fullTimeValues(form){const note=new FormData(form).get('note').trim(),alreadyEnded=state.clock.period==='fulltime',seconds=alreadyEnded?state.clock.seconds:liveSeconds(state.clock),endedPeriod=state.clock.endedPeriod||(state.clock.period==='second'?'second':'first');return{note,seconds,endedPeriod}}
