document.addEventListener('click',event=>{if(event.target.closest('#reopen-session'))reopenSession();if(event.target.closest('#download-backup'))downloadMatchBackup();if(event.target.closest('#download-structured'))downloadStructuredExport();if(event.target.closest('#download-handoff'))downloadHandoffReport();if(event.target.closest('#choose-backup'))document.querySelector('#backup-file')?.click();if(event.target.closest('#confirm-restore'))confirmRestore();if(event.target.closest('#report-notes'))openAssessments();if(event.target.closest('#add-team-two'))beginTeamTwo();const special=event.target.closest('[data-special]');if(special)selectSpecial(special.dataset.special);if(event.target.closest('.back-other')){draftObservation.stage='other';render()}});
